import { uid } from 'quasar';
import { workflowSplitDelimiter } from 'src/constants';
import { useWorkflowBuilderStore, useDropdownStore } from 'src/store/main';
import { useWorkflowLogsVariablesStore } from 'src/store/WorkflowBuilder/workflow_logs_variables.store';
import { storeToRefs } from 'pinia';
import { getVariableData } from 'src/pages/WorkflowBuilder/generic_card_functions';
import { mergeTemplateVariableMetadata } from 'src/pages/WorkflowBuilder/workflow-variable-handler';

type CardVariable = {
  id: string;
  uuid?: string;
  display_name: string;
  data: any;
  data_type?: string;
  dependency_variables?: string[];
  is_list?: boolean;
};

type Card = {
  variables?: CardVariable[];
};

/**
 * Build the dropdown data map that getVariableData expects.
 * Merges data from both the dropdown store and the workflow logs variable store,
 * matching the same structure used in generic_card_logs.vue's prepareDataForVariableReplacement.
 */
function buildDropdownData(): Record<string, any[]> {
  const dropdownStore = useDropdownStore();
  const { subOrgList, email_template_list } = storeToRefs(dropdownStore);

  const logsStore = useWorkflowLogsVariablesStore();
  const { users, groups, workflows, decision_tables, doc_operator_prompts } = storeToRefs(logsStore);

  return {
    users: users.value || [],
    groups: groups.value || [],
    workflows: workflows.value || [],
    decision_tables: decision_tables.value || [],
    subOrgList: subOrgList.value || [],
    prompts: doc_operator_prompts.value || [],
    email_templates: email_template_list.value || [],
  };
}

/**
 * Look up a card template from the workflow builder store catalogs.
 * Returns the template card with its original variable IDs (from the translation text).
 * Requires card catalogs to be loaded (call store.getWorkflowAllCards() first).
 */
function findTemplateCard(cardId: string, categoryName: string): any | null {
  const store = useWorkflowBuilderStore();
  const catalogs = [
    store.workflowWhenCards,
    store.workflowAndCards,
    store.workflowThenCards,
  ];
  for (const catalog of catalogs) {
    if (!Array.isArray(catalog)) continue;
    const category = catalog.find((cat: any) => cat.category === categoryName);
    if (!category?.cards) continue;
    const card = category.cards.find((c: any) => c.id === cardId);
    if (card) return card;
  }
  return null;
}

/**
 * Look up sensitive variable names for a DocOperator card's script_data.
 * Checks the designer's docOperatorLockedSensitiveData first, then falls back
 * to the prompts list (from dropdown store or logs variable store).
 */
function findSensitiveKeys(scriptDataUuid: string, scriptId: string | null): string[] {
  // Designer state: populated by processCardVariablesForLoad
  const store = useWorkflowBuilderStore();
  const { docOperatorLockedSensitiveData } = storeToRefs(store);
  const fromDesigner = docOperatorLockedSensitiveData.value?.[scriptDataUuid];
  if (Array.isArray(fromDesigner) && fromDesigner.length > 0) return fromDesigner;

  // Fallback for logs context: look up prompt by script ID in available stores
  if (scriptId) {
    // Try logs variable store (raw API data with sensitive_variables field)
    const logsStore = useWorkflowLogsVariablesStore();
    const { doc_operator_prompts: logsPromptsRef } = storeToRefs(logsStore);
    const logsPrompts = logsPromptsRef.value || [];
    const logsPrompt = logsPrompts.find((p: any) => p.id === scriptId || p.value === scriptId);
    if (logsPrompt?.sensitive_variables) {
      const sv = typeof logsPrompt.sensitive_variables === 'string'
        ? JSON.parse(logsPrompt.sensitive_variables)
        : logsPrompt.sensitive_variables;
      if (Array.isArray(sv) && sv.length > 0) return sv;
    }

    // Try dropdown store (designer format: { value, label, sensitive_variables })
    const dropdownStore = useDropdownStore();
    const ddPrompts = (dropdownStore as any).doc_operator_prompts || [];
    const ddPrompt = ddPrompts.find((p: any) => p.value === scriptId);
    if (ddPrompt?.sensitive_variables) {
      const sv = typeof ddPrompt.sensitive_variables === 'string'
        ? JSON.parse(ddPrompt.sensitive_variables)
        : ddPrompt.sensitive_variables;
      if (Array.isArray(sv) && sv.length > 0) return sv;
    }
  }

  return [];
}

/**
 * Mask sensitive script_data variable values with '***' for read-only display.
 *
 * Finds the script_data variable, identifies which keys are sensitive (from
 * designer state or prompts list fallback), and replaces their values.
 */
export function maskSensitiveCardVariables(card: any): void {
  if (!card?.variables?.length) return;

  const scriptVar = card.variables.find((v: any) => v.display_name === 'script');
  const scriptDataVar = card.variables.find((v: any) => v.display_name === 'script_data');
  if (!scriptDataVar?.data) return;

  const sensitiveKeys = findSensitiveKeys(scriptDataVar.uuid || '', scriptVar?.data || null);
  if (sensitiveKeys.length === 0) return;

  let parsed: Record<string, any>;
  try {
    parsed = JSON.parse(scriptDataVar.data);
  } catch {
    return;
  }

  let changed = false;
  for (const key of sensitiveKeys) {
    if (Object.prototype.hasOwnProperty.call(parsed, key) && parsed[key]) {
      parsed[key] = '***';
      changed = true;
    }
  }

  if (changed) {
    scriptDataVar.data = JSON.stringify(parsed);
  }
}

/**
 * Pre-populate workflowModel entries for card variables so that Badge.vue
 * displays resolved values in read-only contexts (logs viewer, test results).
 *
 * Reuses getVariableData from generic_card_functions.ts — the same resolution
 * logic used by generic_card_logs.vue — to avoid duplication.
 *
 * @param uuidPrefix - Optional prefix to namespace workflowModel keys, useful
 *   when multiple cards share the same variable uuid in read-only views.
 *
 * Call this once per card when rendering cards outside the designer.
 */
export function populateWorkflowModelForCard(card: any, uuidPrefix?: string): void {
  if (!card?.variables?.length) return;

  const workflowBuilderStore = useWorkflowBuilderStore();
  const { workflowModel } = storeToRefs(workflowBuilderStore);
  const dropdownData = buildDropdownData();

  // Ensure variable IDs match the card template (backend may return variables
  // in a different order). Look up the template card from the store catalog.
  // Requires card catalogs to be loaded (workflowLogsv2 calls getWorkflowAllCards).
  if (card.id && card.category) {
    const templateCard = findTemplateCard(card.id, card.category);
    if (templateCard?.variables) {
      mergeTemplateVariableMetadata(card.variables, templateCard.variables);
    }
  }

  for (const variable of card.variables) {
    if (!variable.uuid) {
      variable.uuid = uid();
    }

    const modelKey = uuidPrefix ? `${uuidPrefix}${variable.uuid}` : variable.uuid;

    // Skip if already resolved. Using _resolved flag (not badgeValue !== defaultValue)
    // so entries populated with raw values before dropdown data loaded get re-resolved.
    const existing = workflowModel.value[modelKey];
    if (existing?._resolved) {
      continue;
    }

    // Use getVariableData with the __%id__% format it expects
    const varId = `${workflowSplitDelimiter}${variable.id}${workflowSplitDelimiter}`;
    const resolved = getVariableData(varId, card as any, dropdownData);
    const badgeValue = resolved || variable.display_name;

    workflowModel.value[modelKey] = {
      value: variable.data ?? '',
      badgeValue,
      defaultValue: variable.display_name,
      dependency_variables: variable.dependency_variables,
      is_list: variable.is_list,
      _resolved: true,
    };
  }
}
