import { defineStore } from 'pinia'
import { useUserStore } from 'src/store/main';
import { useDropdownStore } from 'src/store/Dropdown/dropdown.store';
import type { dynamicObj } from 'src/pages/assets';
import { decisionApiService, userApiService, workflowApiService } from 'src/services';
import { operatorApiService } from 'src/services';
import { ref } from 'vue';
import {i18n} from 'src/boot/i18n';
import { invalid, CONSTANTS } from 'src/constants';
import { buildNodeLogMessage } from 'src/pages/WorkflowBuilder/composables/useNodeLogMessage';
import { notify } from 'src/components/notifications/notify';
import { tol } from 'src/boot/tolgee';


export const useWorkflowLogsVariablesStore = defineStore('workflow_logs_variables_store', {
  
  state: () => ({
    users: [] as any,
    groups: [] as any,
    workflows: [] as any,
    decision_tables: [] as any,
    doc_operator_prompts: [] as any,
    logs: ref([] as any),
    wf_logs: ref({} as dynamicObj),
    card_messages: ref({} as dynamicObj),
    dashboard_tab_active: ref(false),
    order_by: {} as dynamicObj,
    init_errors: [] as string[],
  }),
  getters: {
     
    getStoredUsers: (state): string[] => state.users,
  },

  actions: {

    async getUsers() {
      try {
        if (this.users.length == 0) {
          const userStore = useUserStore();
          await userStore.getAllUsers();
          this.users = JSON.parse(JSON.stringify(userStore.allUsers));
        }
      } catch (err) {
        console.error('[Workflow init: users] fetch failed —', err);
        this.init_errors.push('users');
      }
    },

    async getGroups() {
      try {
        if (this.groups.length == 0) {
          const res_groups = await userApiService.getGroups()
          if (res_groups && Array.isArray(res_groups)) {
            res_groups.forEach((group: any) => {
              this.groups.push(group)
            })
          }
        }
      } catch (err) {
        console.error('[Workflow init: groups] fetch failed —', err);
        this.init_errors.push('groups');
      }
    },

    async getWorkflows() {
      try {
        if (this.workflows.length == 0) {
          const res_workflows = await workflowApiService.getWorkflowsForOrg()
          if (res_workflows && Array.isArray(res_workflows)) {
            res_workflows.forEach((workflow: any) => {
              this.workflows.push(workflow)
            })
          }
        }
      } catch (err) {
        console.error('[Workflow init: workflows] fetch failed —', err);
        this.init_errors.push('workflows');
      }
    },

    async getDecisionTables() {
      try {
        if (this.decision_tables.length > 0) {
          return
        }
        const res_decision_tables = await decisionApiService.getAllDecisionTrees(true)
        if (res_decision_tables && res_decision_tables.data && Array.isArray(res_decision_tables.data)) {
          res_decision_tables.data.forEach((decision_table: any) => {
            this.decision_tables.push(decision_table)
          })
        }
      } catch (err) {
        console.error('[Workflow init: decision_tables] fetch failed —', err);
        this.init_errors.push('decision_tables');
      }
    },

    async getDocOperatorPrompts() {
      try {
        if (this.doc_operator_prompts.length > 0) {
          return
        }
        const res_doc_operator_prompts = await operatorApiService.getAllPrompts(false)
        if (res_doc_operator_prompts && res_doc_operator_prompts.data && Array.isArray(res_doc_operator_prompts.data)) {
          res_doc_operator_prompts.data.forEach((prompt: any) => {
            this.doc_operator_prompts.push(prompt)
          })
        }
      } catch (err) {
        console.error('[Workflow init: doc_operator_prompts] fetch failed —', err);
        this.init_errors.push('doc_operator_prompts');
      }
    },

    notifyInitErrorsIfAny(): void {
      if (this.init_errors.length === 0) return;
      const impactByService: Record<string, string> = {
        users: 'user dropdowns and assignee pickers will be empty',
        groups: 'group dropdowns will be empty',
        workflows: 'workflow-reference fields will not list existing workflows',
        decision_tables: 'decision-table dropdowns will be empty',
        doc_operator_prompts: 'DocOperator prompt pickers will be empty',
      };
      const impactLines = this.init_errors
        .map((name) => `  - ${name}: ${impactByService[name] ?? 'related UI will be empty'}`)
        .join('\n');
      console.warn(
        `[Workflow init] ${this.init_errors.length} of 5 services failed:\n${impactLines}\nPage will render with degraded data.`,
      );
      notify.warning(tol.t('workflow_partial_data_warning'));
      this.init_errors = [];
    },

    checkLogSuccessCards(full_workflow_log: any, workflow_log: any, run_category: string, index: number, indexAdditionals = 0): boolean {
       if (![null, undefined].includes(full_workflow_log.workflow_data) && full_workflow_log.workflow_data.when_condition.card_logs != undefined) {
          if (run_category == CONSTANTS.when) {
            const index_log = full_workflow_log.workflow_data.when_condition
            return ['success', 'default'].includes((index_log.card_logs && index_log.card_logs[0]) ? index_log.card_logs[0].card_result : false)
          }
          else if (run_category == CONSTANTS.and) {
            const index_log = full_workflow_log.workflow_data.and_conditions[index]
            return ['success', 'default'].includes((index_log.card_logs && index_log.card_logs[0]) ? index_log.card_logs[0].card_result : false)
          }
          else if (run_category == CONSTANTS.then) {
            const index_log = full_workflow_log.workflow_data.then_conditions[index]
            return ['success', 'default'].includes((index_log.card_logs && index_log.card_logs[0]) ? index_log.card_logs[0].card_result : false)
          }
          else if (run_category == CONSTANTS.additional_conditions) {
            const index_log = full_workflow_log.workflow_data.additional_and_conditions[indexAdditionals][index]
            return ['success', 'default'].includes((index_log.card_logs && index_log.card_logs[0]) ? index_log.card_logs[0].card_result : false)
          }
          else if (run_category == CONSTANTS.additional_executions) {
            const index_log = full_workflow_log.workflow_data.additional_then_executions[indexAdditionals][index]
            return ['success', 'default'].includes((index_log.card_logs && index_log.card_logs[0]) ? index_log.card_logs[0].card_result : false)
          }
          return false
        }
      
        if (run_category == CONSTANTS.when) {
          // always required
          return ['success', 'default'].includes(workflow_log[0][0].card_result)
        }
        else if (run_category == CONSTANTS.and) {
          // and cards optional, after when
          index += 1
          if (workflow_log[index][0].run_category != CONSTANTS.and) {
            return false
          }
          return ['success', 'default'].includes(workflow_log[index][0].card_result)
        }
        else if (run_category == CONSTANTS.then) {
          // then card, required, lenght > 1
          for (let i = 1; i < workflow_log.length; i++) {
            if (workflow_log[i][0].run_category == run_category) {
              return ['success', 'default'].includes(workflow_log[i + index][0].card_result)
            }
          }
        }
        return false
    },
    workflowprepareCardLogs(full_workflow_log: any, workflow_log:any, card_id: string, workflow_run_id: string, index: any, run_category: string, indexAdditionals = 0) {
      const locale = useDropdownStore().getSelectedLanguage();
      const processLogs = (card: any) =>
        (card.card_logs ?? []).map((log: any) =>
          buildNodeLogMessage(log, card.partner_translations ?? null, locale),
        );

       if (full_workflow_log.workflow_data.when_condition.card_logs != undefined) {
        if (run_category == CONSTANTS.when) {
          this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category] = processLogs(full_workflow_log.workflow_data.when_condition)
          return
        }
        else if (run_category == CONSTANTS.and) {
          this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category] = processLogs(full_workflow_log.workflow_data.and_conditions[index])
          return
        }
        else if (run_category == CONSTANTS.then) {
          this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category] = processLogs(full_workflow_log.workflow_data.then_conditions[index])
          return
        }
        else if (run_category == CONSTANTS.additional_conditions) {
          this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category + indexAdditionals] = processLogs(full_workflow_log.workflow_data.additional_and_conditions[indexAdditionals][index])
          return
        }
        else if (run_category == CONSTANTS.additional_executions) {
          this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category + indexAdditionals] = processLogs(full_workflow_log.workflow_data.additional_then_executions[indexAdditionals][index])
          return
        }
      }
      const processRawLogs = (rawLogs: any[], partnerTranslations: any) =>
        rawLogs.map((log: any) => buildNodeLogMessage(log, partnerTranslations ?? null, locale));

      const wfData = full_workflow_log?.workflow_data;
      if (run_category == CONSTANTS.when) {
        const pt = wfData?.when_condition?.partner_translations ?? null;
        this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category] = processRawLogs(workflow_log[0] ?? [], pt)
      }
      else if (run_category == CONSTANTS.and) {
        for (let i = 1; i < workflow_log.length; i++) {
          if (i == index + 1) {
            const pt = wfData?.and_conditions?.[index]?.partner_translations ?? null;
            this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category] = processRawLogs(workflow_log[i] ?? [], pt)
            break
          }
        }
      }
      else if (run_category == CONSTANTS.then) {
        for (let i = 0; i < workflow_log.length; i++) {
          if (workflow_log[i][0].run_category == run_category) {
            const pt = wfData?.then_conditions?.[index]?.partner_translations ?? null;
            this.card_messages[card_id.toString() + workflow_run_id.toString() + index + '_' + run_category] = processRawLogs(workflow_log[i + index] ?? [], pt)
            break
          }
        }
      }
    },
    translateData(data: dynamicObj) {
      const data_keys = Object.keys(data)
      for (const dkey of data_keys) {
        if (data[dkey] && data[dkey].includes(', ')) {
          const transl_keys: string[] = data[dkey].split(', ')
          for (let i = 0; i < transl_keys.length; i++) {
            const var_transl: string = i18n.t(transl_keys[i], transl_keys[i]);
            if (transl_keys[i] == var_transl) {
              transl_keys[i] = i18n.t(transl_keys[i].toLowerCase(), transl_keys[i]) != invalid ? i18n.t(transl_keys[i].toLowerCase(), transl_keys[i]) : transl_keys[i];
            }
            else {
              transl_keys[i] = var_transl
            }
          }
          data[dkey] = transl_keys.join(', ')
        }
        else {
          data[dkey] = i18n.t(data[dkey], data[dkey]) != invalid ? i18n.t(data[dkey], data[dkey]) : data[dkey] ;
        }
      }
      return data
    },
    

  },

})